(4611821, 664472, 15291, '<td valign="top">Nice capture, the first couple of sprouts at there base seems a little hot.</td>', 'Nice capture, the first couple of sprouts at there base seems a little hot.', '2008-04-03 19:40:34.000000', NULL, 1),
(4611828, 663463, 15291, '<td valign="top">Nicely done, a bit over exposed I think.</td>', 'Nicely done, a bit over exposed I think.', '2008-04-03 19:41:43.000000', NULL, 1),
(4611831, 660045, 15291, '<td valign="top">Nicely done, great detail &amp; catch light.</td>', 'Nicely done, great detail & catch light.', '2008-04-03 19:42:41.000000', NULL, 1),
(4611834, 663204, 15291, '<td valign="top">Nice image.</td>', 'Nice image.', '2008-04-03 19:43:43.000000', NULL, 1),
(4611847, 664128, 15291, '<td valign="top">Nice image.</td>', 'Nice image.', '2008-04-03 19:50:54.000000', NULL, 1),
