(4612087, 662416, 74534, '<td valign="top">Good choice of duotone, but I believe you could have extracted more detail and texture in the grass.</td>', 'Good choice of duotone, but I believe you could have extracted more detail and texture in the grass.', '2008-04-03 22:20:29.000000', NULL, 1),
(4612089, 663988, 74534, '<td valign="top">This is a good shot with beautiful colors, but it feels a bit over processed. Good composition, with the rocks in the foreground and subject by the rule of thirds.</td>', 'This is a good shot with beautiful colors, but it feels a bit over processed. Good composition, with the rocks in the foreground and subject by the rule of thirds.', '2008-04-03 22:21:33.000000', NULL, 1),
(4612091, 664448, 74534, '<td valign="top">Very good higher key image, with good use of toning. Seems to lack a clear point of focus an interest though.</td>', 'Very good higher key image, with good use of toning. Seems to lack a clear point of focus an interest though.', '2008-04-03 22:22:32.000000', NULL, 1),
