(4612843, 659527, 66635, '<td valign="top">Yummy!</td>', 'Yummy!', '2008-04-04 06:06:33.000000', NULL, 1),
(4612844, 660447, 66635, '<td valign="top">Really nice!  Love the white against the blue.</td>', 'Really nice!  Love the white against the blue.', '2008-04-04 06:06:53.000000', NULL, 1),
