(4612847, 657301, 66635, '<td valign="top">Beautiful.  I miss snow.</td>', 'Beautiful.  I miss snow.', '2008-04-04 06:08:17.000000', NULL, 1),
(4612848, 663460, 66635, '<td valign="top">Too cool!  Such incredible detail.  Really great!</td>', 'Too cool!  Such incredible detail.  Really great!', '2008-04-04 06:08:39.000000', NULL, 1),
