(4612874, 661686, 66635, '<td valign="top">Great expression.  He looks like he''s smiling.</td>', 'Great expression.  He looks like he''s smiling.', '2008-04-04 06:19:50.000000', NULL, 1),
(4612876, 663023, 66635, '<td valign="top">Wow!</td>', 'Wow!', '2008-04-04 06:20:02.000000', NULL, 1),
