(4613835, 657737, 73942, '<td valign="top">Beautiful shot, may want to crop out the fence, I find it takes away from this shot.</td>', 'Beautiful shot, may want to crop out the fence, I find it takes away from this shot.', '2008-04-04 13:20:20.000000', NULL, 1),
(4613838, 662424, 76598, '<td valign="top">Absolutely incredible photo, great focus on eyes, incredible color and contrast.</td>', 'Absolutely incredible photo, great focus on eyes, incredible color and contrast.', '2008-04-04 13:21:46.000000', NULL, 1),
(4613845, 663951, 11854, '<td valign="top">Nice lighting. I would have really loved if you could have moved those few branches out of his face.</td>', 'Nice lighting. I would have really loved if you could have moved those few branches out of his face.', '2008-04-04 13:24:43.000000', NULL, 1),
