INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4619334, 664308, 62006, '<td valign="top">Very nice macro. It seems a little oversharpened for my taste. Very nice colors.</td>', 'Very nice macro. It seems a little oversharpened for my taste. Very nice colors.', '2008-04-06 23:05:03.000000', NULL, 1),
(4619341, 661723, 62006, '<td valign="top">Beautiful capture. Vibrant colors and sharp focus.</td>', 'Beautiful capture. Vibrant colors and sharp focus.', '2008-04-06 23:07:23.000000', NULL, 1),
(4619366, 663698, 88575, '<td valign="top">I love this!  Mystical and beautiful.</td>', 'I love this!  Mystical and beautiful.', '2008-04-06 23:16:38.000000', NULL, 1),
(4619417, 664168, 23430, '<td valign="top">Beautiful scene. Nice mellow tones and colours.</td>', 'Beautiful scene. Nice mellow tones and colours.', '2008-04-06 23:30:49.000000', NULL, 1),
(4619426, 663809, 23430, '<td valign="top">Great shot. Very out of the box. Good lighting on the subject.</td>', 'Great shot. Very out of the box. Good lighting on the subject.', '2008-04-06 23:33:49.000000', NULL, 1),
(4619429, 662762, 23430, '<td valign="top">Dynamic shot, I like the muted tones and the space around your subject.</td>', 'Dynamic shot, I like the muted tones and the space around your subject.', '2008-04-06 23:35:33.000000', NULL, 1),
(4619473, 658487, 82022, '<td valign="top">Great perspective! Wide angle was definitely the way to go.</td>', 'Great perspective! Wide angle was definitely the way to go.', '2008-04-06 23:53:39.000000', NULL, 1),
(4619474, 664277, 82022, '<td valign="top">Great colors, the snowboarder really pops out.</td>', 'Great colors, the snowboarder really pops out.', '2008-04-06 23:54:20.000000', NULL, 1),
(4619481, 664481, 8624, '<td valign="top">excellent shot! great idea. the illusion would be stronger if the balloons were above her head, though. I love the polka dot dress and black and white balloons.</td>', 'excellent shot! great idea. the illusion would be stronger if the balloons were above her head, though. I love the polka dot dress and black and white balloons.', '2008-04-06 23:55:25.000000', NULL, 1),
(4619502, 663223, 82022, '<td valign="top">Looks like a top 10 shot to me!</td>', 'Looks like a top 10 shot to me!', '2008-04-07 00:00:59.000000', NULL, 1),
(4619541, 663951, 8624, '<td valign="top">love the lighting, love the pose. I wish the branches were not occluding the swubject</td>', 'love the lighting, love the pose. I wish the branches were not occluding the swubject', '2008-04-07 00:12:53.000000', NULL, 1),
(4619579, 658062, 89940, '<td valign="top">The lighting is lighting the background more than the flower. The blue cast it gives on the flower makes it look unattractive.</td>', 'The lighting is lighting the background more than the flower. The blue cast it gives on the flower makes it look unattractive.', '2008-04-07 00:23:31.000000', NULL, 1),
(4619587, 662356, 89940, '<td valign="top">I kind of like the lighting on this. Don''t like that the left edge of the pink dot is cut off. Overall I find the subject uninteresting.</td>', 'I kind of like the lighting on this. Don''t like that the left edge of the pink dot is cut off. Overall I find the subject uninteresting.', '2008-04-07 00:25:15.000000', NULL, 1),
(4619591, 659967, 89940, '<td valign="top">Nice job capturing the action, but it looks like a snapshot. Perhaps having a shallower DOF would help. Or paying more attention to the background.</td>', 'Nice job capturing the action, but it looks like a snapshot. Perhaps having a shallower DOF would help. Or paying more attention to the background.', '2008-04-07 00:26:45.000000', NULL, 1),
(4619656, 662059, 5391, '<td valign="top">Just lovely.  A fantastic capture.  9</td>', 'Just lovely.  A fantastic capture.  9', '2008-04-07 00:58:41.000000', NULL, 1),
(4619666, 660165, 5391, '<td valign="top">Excellent capture.  The interaction between the subject and the camera is beautiful.  Great tonal range, color palette and angle, also.  10</td>', 'Excellent capture.  The interaction between the subject and the camera is beautiful.  Great tonal range, color palette and angle, also.  10', '2008-04-07 01:03:30.000000', NULL, 1),
(4619668, 663347, 5391, '<td valign="top">Interesting lines and colors.  Very compelling image.  8</td>', 'Interesting lines and colors.  Very compelling image.  8', '2008-04-07 01:04:36.000000', NULL, 1),
(4619678, 664166, 5391, '<td valign="top">Beautiful detail and lovely monochromatic effect.  8</td>', 'Beautiful detail and lovely monochromatic effect.  8', '2008-04-07 01:06:14.000000', NULL, 1),
(4619684, 664130, 5391, '<td valign="top">Awwww...  cute!</td>', 'Awwww...  cute!', '2008-04-07 01:07:41.000000', NULL, 1),
(4619690, 663223, 5391, '<td valign="top">Creative capture of an absolutely stunning young woman.  I can''t take my eyes off of it.  10+</td>', 'Creative capture of an absolutely stunning young woman.  I can''t take my eyes off of it.  10+', '2008-04-07 01:09:16.000000', NULL, 1),
(4619756, 662890, 77838, '<td valign="top">Very cool reflection, even following the puddle to the edge of the frame you can see ''building''.<br/> <br/>I don''t really care for the drain being right over the one building but it does kind of break up a perfect mirror. -BB</td>', 'Very cool reflection, even following the puddle to the edge of the frame you can see ''building''. I don''t really care for the drain being right over the one building but it does kind of break up a perfect mirror. -BB', '2008-04-07 01:22:36.000000', NULL, 1),
(4619775, 664200, 77838, '<td valign="top">What a perfect reflection, the clouds in this photo really help boost it also.  It''s such a perfect symmetrical photo! I don''t really have much of a critique, sorry. -BB</td>', 'What a perfect reflection, the clouds in this photo really help boost it also.  It''s such a perfect symmetrical photo! I don''t really have much of a critique, sorry. -BB', '2008-04-07 01:26:47.000000', NULL, 1),
(4619786, 662069, 77838, '<td valign="top">What a great smile she has!  The reflections give it a little different feel than a straight "studio" shot.  I like it. -BB</td>', 'What a great smile she has!  The reflections give it a little different feel than a straight "studio" shot.  I like it. -BB', '2008-04-07 01:29:05.000000', NULL, 1),
(4619789, 664481, 5391, '<td valign="top">Oh, my.  Straight out of the pages of Vogue.  Perfection.  10</td>', 'Oh, my.  Straight out of the pages of Vogue.  Perfection.  10', '2008-04-07 01:29:18.000000', NULL, 1),
(4619793, 664380, 77838, '<td valign="top">You have some amazing colors here.  I like the way you used the two buildings on the sides to frame the main building.  Very cool shot. -BB</td>', 'You have some amazing colors here.  I like the way you used the two buildings on the sides to frame the main building.  Very cool shot. -BB', '2008-04-07 01:30:19.000000', NULL, 1),
(4619799, 663188, 5391, '<td valign="top">Lots of really great shots in this challenge.  This is one of the best.  Should be in a calendar.  10</td>', 'Lots of really great shots in this challenge.  This is one of the best.  Should be in a calendar.  10', '2008-04-07 01:31:16.000000', NULL, 1),
(4619803, 660648, 5391, '<td valign="top">Fantastic environmental portrait.  10</td>', 'Fantastic environmental portrait.  10', '2008-04-07 01:31:56.000000', NULL, 1),
(4619808, 656319, 77838, '<td valign="top">I want to guess...is it the constellation: "<a href="//en.wikipedia.org/wiki/Pleiades_(star_cluster)" rel="nofollow" target="_blank">Pleiades</a>"?<br/> <br/>Very beautiful.  It''s hard to believe that there is that much reddish/pink color in the deep sky like this.  Very cool shot. -BB</td>', 'I want to guess...is it the constellation: "Pleiades"? Very beautiful.  It''s hard to believe that there is that much reddish/pink color in the deep sky like this.  Very cool shot. -BB', '2008-04-07 01:33:28.000000', NULL, 1),
(4619826, 664150, 77838, '<td valign="top">The extra large border and the almost completely blown out background give this more of a relaxed casual feel (a good feeling, by the way).  She seems so calm and mild with her head resting on a rock, post, etc.<br/> <br/>I like the angle/POV but wish the far side of her face and forehead weren''t quite so bright.  That''s my only critique for this great shot. -BB</td>', 'The extra large border and the almost completely blown out background give this more of a relaxed casual feel (a good feeling, by the way).  She seems so calm and mild with her head resting on a rock, post, etc. I like the angle/POV but wish the far side of her face and forehead weren''t quite so bright.  That''s my only critique for this great shot. -BB', '2008-04-07 01:36:58.000000', NULL, 1),
(4619844, 663865, 5391, '<td valign="top">Quite captivating macro.  Makes me want to get close to something with my camera.  Beautiful colors.  I''m not sure I wouldn''t have changed the lines in the composition a bit, but it''s very lovely.</td>', 'Quite captivating macro.  Makes me want to get close to something with my camera.  Beautiful colors.  I''m not sure I wouldn''t have changed the lines in the composition a bit, but it''s very lovely.', '2008-04-07 01:40:32.000000', NULL, 1),
(4619848, 664225, 5391, '<td valign="top">I like the rays of sunlight and the bits of pink on the tops of the rocks which are otherwise a lovely contrasting blue color.  8</td>', 'I like the rays of sunlight and the bits of pink on the tops of the rocks which are otherwise a lovely contrasting blue color.  8', '2008-04-07 01:41:24.000000', NULL, 1),
(4619850, 662415, 77838, '<td valign="top">Awesome colors and this is about as close to what I would image the "perfect heavenly" location looking like.  <br/> <br/>With your PP it makes this feel more like a painting instead of a photograph. -BB</td>', 'Awesome colors and this is about as close to what I would image the "perfect heavenly" location looking like.   With your PP it makes this feel more like a painting instead of a photograph. -BB', '2008-04-07 01:41:43.000000', NULL, 1),
(4619854, 661620, 5391, '<td valign="top">Ahhhh...  A little piece of heaven.  Isolated paradise captured on film.  I love it.  8</td>', 'Ahhhh...  A little piece of heaven.  Isolated paradise captured on film.  I love it.  8', '2008-04-07 01:43:11.000000', NULL, 1),
(4619855, 656858, 77838, '<td valign="top">Almond blossoms! Looks similar to some of my last shots  The blue background is very complimentary to the white and pink blossoms. -BB</td>', 'Almond blossoms! Looks similar to some of my last shots  The blue background is very complimentary to the white and pink blossoms. -BB', '2008-04-07 01:43:25.000000', NULL, 1),
(4619865, 663178, 77838, '<td valign="top">Awesome silhouettes and you have a great DOF too.  The border really helps the black contrast good with the deep reddish/orange sky.</td>', 'Awesome silhouettes and you have a great DOF too.  The border really helps the black contrast good with the deep reddish/orange sky.', '2008-04-07 01:45:24.000000', NULL, 1),
(4619869, 662564, 77838, '<td valign="top">Very interesting POV for this type of photo.  I really like the use of blank space above her also.  It feels like there is a waiting for something more. Wonderful capture.  -BB</td>', 'Very interesting POV for this type of photo.  I really like the use of blank space above her also.  It feels like there is a waiting for something more. Wonderful capture.  -BB', '2008-04-07 01:46:18.000000', NULL, 1),
(4619871, 664479, 5391, '<td valign="top">Gorgeous.  Fantastic use of a wide angle lens, and the contrast between the cool blue colors and that thin ribbon of warm colors (along with the light in the building) is just captivating.  9</td>', 'Gorgeous.  Fantastic use of a wide angle lens, and the contrast between the cool blue colors and that thin ribbon of warm colors (along with the light in the building) is just captivating.  9', '2008-04-07 01:46:43.000000', NULL, 1),
(4619877, 662712, 5391, '<td valign="top">I love tigers, and when I see one photographed this well, it just makes me want to stare at it forever.  I want to reach into my monitor and sink my fingers in that thick fur and listen to its low growl/purr noises.  (And then probably lose my fingers...)  Well done.  8</td>', 'I love tigers, and when I see one photographed this well, it just makes me want to stare at it forever.  I want to reach into my monitor and sink my fingers in that thick fur and listen to its low growl/purr noises.  (And then probably lose my fingers...)  Well done.  8', '2008-04-07 01:48:36.000000', NULL, 1),
(4619881, 663002, 77838, '<td valign="top">Nice pun!  I like the little noose too.  I think the B&amp;W helps the drama here is this photo.  Cool photo. -BB</td>', 'Nice pun!  I like the little noose too.  I think the B&W helps the drama here is this photo.  Cool photo. -BB', '2008-04-07 01:49:57.000000', NULL, 1),
(4619882, 658329, 5391, '<td valign="top">I understand the reluctance of the nude model, possibly moreso the pregnant nude, but his is just so gorgeous that I feel let down that there aren''t eyes and a face to connect with.  Beautiful baby bump.  :)  7</td>', 'I understand the reluctance of the nude model, possibly moreso the pregnant nude, but his is just so gorgeous that I feel let down that there aren''t eyes and a face to connect with.  Beautiful baby bump.  :)  7', '2008-04-07 01:50:26.000000', NULL, 1),
(4619887, 656627, 5391, '<td valign="top">Wow.  Just...  wow.  10</td>', 'Wow.  Just...  wow.  10', '2008-04-07 01:51:13.000000', NULL, 1),
(4619898, 661583, 5391, '<td valign="top">Wow!  Fantastic color palette and interesting use of the wide angle lens.  I''d like to see the woman engaged with the camera, but it''s quite a lovely image.</td>', 'Wow!  Fantastic color palette and interesting use of the wide angle lens.  I''d like to see the woman engaged with the camera, but it''s quite a lovely image.', '2008-04-07 01:54:15.000000', NULL, 1),
(4619921, 664065, 5391, '<td valign="top">Interesting light on a well known, touching subject matter.  Can''t give this less than a 9.  Partially for being a touching image, partially for the way you''ve captured the tonal range - dark areas showing light lettering, light area showing dark lettering - a tricky principle than the casual viewer may not grasp at a quick glance.  9</td>', 'Interesting light on a well known, touching subject matter.  Can''t give this less than a 9.  Partially for being a touching image, partially for the way you''ve captured the tonal range - dark areas showing light lettering, light area showing dark lettering - a tricky principle than the casual viewer may not grasp at a quick glance.  9', '2008-04-07 01:58:45.000000', NULL, 1),
(4619927, 655665, 5391, '<td valign="top">Beautiful capture of light.  9</td>', 'Beautiful capture of light.  9', '2008-04-07 02:01:16.000000', NULL, 1),
(4619931, 664266, 5391, '<td valign="top">Lovely and peaceful!</td>', 'Lovely and peaceful!', '2008-04-07 02:02:26.000000', NULL, 1),
(4619933, 663412, 5391, '<td valign="top">Like a fairyland!  Wow!</td>', 'Like a fairyland!  Wow!', '2008-04-07 02:03:50.000000', NULL, 1),
